        return 0;

    while (s[len] != '\0')
        len++;

    return len;
}

char *my_strcpy(char *dest, const char *src)
{
    if (dest == NULL)
        return NULL;

    if (src == NULL) {
        dest[0] = '\0';
        return dest;
    }

    char *d = dest;
    while (*src != '\0') {
        *d++ = *src++;
    }
    *d = '\0';

    return dest;
}

char *my_strcat(char *dest, const char *src)
{
    if (dest == NULL)
        return NULL;

    char *end = dest;
    while (*end != '\0')
        end++;

    if (src == NULL)
